def txt(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([txt(v) for v in x])
    if isinstance(x, dict):
        return ' '.join([txt(v) for v in x.values()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def firstmatch(adm, prefix, words):
    for a in adm:
        s = ' ' + a + ' '
        ok = s.startswith(prefix + ' ')
        for w in words:
            if (' ' + w + ' ') not in s:
                ok = False
        if ok:
            return a
    return ''

def hook(ctx, nb):
    task_type = txt(val(ctx, 'task.task_type', ''))
    target = txt(val(ctx, 'task.target_type', ''))
    dest = txt(val(ctx, 'task.destination_type', ''))
    verb = needverb(task_type)
    if not verb:
        nb['transform_done'] = True
        return None
    if target and target in task_type and 'transform' in task_type and target in txt(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', '')))):
        nb['transform_done'] = True
        nb['transformed_item'] = target
    pc = val(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    old = nb.get('placed_count', 0)
    try:
        old = int(old)
    except Exception:
        old = 0
    two = 'two' in task_type
    if two and target and target in task_type and 'pick' in task_type:
        if pc > old:
            nb['transformed_item'] = ''
            nb['transform_done'] = False
    inv = txt(val(ctx, 'world.inventory', ''))
    carrying = bool(target and target in inv and 'nothing' not in inv and 'not carrying' not in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target and target not in inv)
    take_here = bool(target and firstmatch(val(ctx, 'admissible', []), 'take ' + target, [target]))
    act = txt(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    if act and 'pick ' in act and target and target in act and two and target in task_type and 'pick' in task_type and ' from ' in act:
        source = act.split(' from ', 1)[1]
        locs = txt(val(ctx, 'world.placed_locations', ''))
        if source and source in locs and old >= 0:
            nb['placed_count'] = max(old, pc - 1)
    if two and target and target in task_type and 'pick' in task_type:
        try:
            nb['placed_count'] = int(val(ctx, 'world.placed_count', nb.get('placed_count', 0)))
        except Exception:
            nb['placed_count'] = old
    if wrong:
        stage = 'wrong_inventory'
    elif carrying:
        if verb and not nb.get('transform_done'):
            stage = 'transform'
        else:
            stage = 'go_destination'
    elif take_here:
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = task_type
    nb['transform_verb'] = verb
    return None

