def emit(nb, msg):
    if not msg or nb.get('last_hint') == msg:
        return None
    nb['last_hint'] = msg
    return {'message': msg}

def hook(ctx, nb):
    task_type = nb.get('task_type') or txt(val(ctx, 'task.task_type', ''))
    target = nb.get('target_type') or txt(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or txt(val(ctx, 'task.destination_type', ''))
    verb = nb.get('transform_verb') or needverb(task_type)
    stage = nb.get('stage') or 'find_target'
    pc = nb.get('placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if verb and target and stage == 'transform' and not nb.get('transform_done'):
        return emit(nb, 'You are carrying the requested ' + target + '. Use an admissible ' + verb + ' action on it before going to the final destination.')
    if 'two' in task_type and target and 'pick' in task_type and pc >= 1 and stage in ['find_target', 'take_target']:
        return emit(nb, 'This is a pick-two task. Do not take back the ' + target + ' already placed at the destination; find another one and use the same destination.')
    if stage == 'put_target' and target and dest:
        return emit(nb, 'You are at the destination with the ' + target + '. Put it in/on the ' + dest + ' now instead of closing or carrying it away.')
    if stage == 'wrong_inventory' and target:
        return emit(nb, 'You appear to be carrying a non-target item. Do not place it as the goal; recover and then take the requested ' + target + '.')
    return None

