def hook(ctx, nb):
    task_type = nb.get('task_type') or txt(val(ctx, 'task.task_type', ''))
    target = nb.get('target_type') or txt(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or txt(val(ctx, 'task.destination_type', ''))
    verb = nb.get('transform_verb') or needverb(task_type)
    if not verb or not target:
        return None
    adm = val(ctx, 'admissible', []) or []
    inv = txt(val(ctx, 'world.inventory', ''))
    carrying = bool(target in inv and 'nothing' not in inv and 'not carrying' not in inv)
    transform_ready = bool(carrying and firstmatch(adm, verb + ' ' + target, [target]))
    transform_late = bool(carrying and 'transform' in task_type and verb in task_type and not nb.get('transform_done') and not transform_ready and targetpresent(adm, [target]))
    if transform_late and not nb.get('transform_hint_done'):
        nb['transform_hint_done'] = True
        return {'kind': 'block_and_prompt', 'message': 'The target is ready to be transformed but no ' + verb + ' action is available here. Do not put or carry the target away; keep it with you and go to a place where ' + verb + ' is admissible.'}
    if transform_ready and not nb.get('transform_ready_hint_done'):
        nb['transform_ready_hint_done'] = True
        return {'kind': 'block_and_prompt', 'message': 'A required ' + verb + ' action for the carried ' + target + ' is available now. Use that transform before any destination put.'}
    two = 'two' in task_type and 'pick' in task_type
    placed = bool(two and nb.get('placed_count', 0) > 0)
    take_target = bool(target and firstmatch(adm, 'take ' + target, [target]))
    take_dest = bool(placed and target and firstmatch(adm, 'take ' + target, [target, dest]))
    if placed and take_target and not take_dest and nb.get('stage') == 'find_target' and (val(ctx, 'predicates.same_action_repeated', False) or val(ctx, 'predicates.same_observation_repeated', False) or val(ctx, 'predicates.remaining_steps_low', False)):
        return {'kind': 'block_and_prompt', 'message': 'Do not search for another ' + target + ' by taking back an item already at the destination. Look elsewhere for a different target item.'}
    return None
